package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.*;
import com.vandorlabs.redstone.ChannelList;
import com.vandorlabs.neoforge.redstone.NativeRedstoneChannels;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Blocks;
/** Actual production service edits against Source bank and saved-row expectations for all supported slots. */
final class ScreenRowEditChecks {
 static void run(ServerLevel world,java.util.Map<ScreenFamily,NativeScreenBlock> blocks)throws Exception{
  JsonObject reference;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenRowEditsReference")))){reference=JsonParser.parseReader(reader).getAsJsonObject();}BlockPos pos=new BlockPos(4300,90,4300);world.getChunkAt(pos);((net.minecraft.world.level.storage.ServerLevelData)world.getLevelData()).setGameTime(100);NativeScreenEntity owner=null;int checks=0;
  for(var entry:reference.getAsJsonArray("cases")){var expected=entry.getAsJsonObject();var family=ScreenFamily.fromId(expected.get("id").getAsString());int slot=expected.get("slot").getAsInt();if(expected.get("step").getAsInt()==0){world.setBlock(pos,Blocks.AIR.defaultBlockState(),2);world.setBlock(pos,blocks.get(family).defaultBlockState(),2);owner=(NativeScreenEntity)world.getBlockEntity(pos);owner.onLoad();NativeRedstoneChannels.flush(world);}NativeScreenControlService service=owner.controlService();if(checks==0)ScreenBlockChecks.changedObserver=observed->{ScreenBlockChecks.changedObserver=null;if(observed.controlService().configure(slot,new NativeScreenRowEdit("Reentry",java.util.List.of())))throw new AssertionError("Reentrant observer replaced an in-flight row edit");};String action=expected.get("action").getAsString();boolean accepted=switch(action){case "toggle"->service.toggle(slot,expected.get("arg").getAsInt());case "pulse"->service.pulse(slot,0);case "slider"->service.select(slot,2,expected.get("arg").getAsInt());case "disable"->service.setEnabled(slot,false);default->edit(service,slot,expected);};if(accepted!=expected.get("accepted").getAsBoolean())throw new AssertionError("Row edit acceptance differs "+expected);CompoundTag actual=new CompoundTag();owner.controls(slot).write(actual);CompoundTag source=TagParser.parseTag(expected.get("saved").getAsString());if(!actual.equals(source))throw new AssertionError("Row edit saved state differs family="+family+" slot="+slot+" step="+expected.get("step")+" actual="+actual+" source="+source);var levels=expected.getAsJsonArray("levels");for(int i=0;i<4;i++)if(NativeRedstoneChannels.level(world,pos,73261+i)!=levels.get(i).getAsInt())throw new AssertionError("Row edit bank differs "+expected);checks++;}
  world.setBlock(pos,Blocks.AIR.defaultBlockState(),2);if(checks!=126||!reference.get("sha256").getAsString().equals("59307828c1a968a1343011e722051bfaff30511f650fcc6a28c473a24e897f9f"))throw new AssertionError("Source row edit coverage");System.out.println("Native Screen row edits PASS actual Source configurations/banks="+checks);
 }
 private static boolean edit(NativeScreenControlService service,int slot,JsonObject expected)throws Exception{try{ListTag rows=TagParser.parseTag("{Rows:"+expected.get("rows").getAsString()+"}").getList("Rows",Tag.TAG_COMPOUND);java.util.List<NativeScreenRowEdit.Row> choices=new java.util.ArrayList<>();for(int i=0;i<rows.size();i++){CompoundTag row=rows.getCompound(i);choices.add(new NativeScreenRowEdit.Row(row.getString("Label"),ChannelList.of(row.getIntArray("RedstoneChannels")),row.getBoolean("Slider"),row.getBoolean("Pulse"),row.getInt("Min"),row.getInt("Max")));}return service.configure(slot,new NativeScreenRowEdit(expected.get("title").getAsString(),choices));}catch(IllegalArgumentException invalid){return false;}}
}
